contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept inputs: amount to send and a dummy flag to allow different call scenarios.
    // amount is used to call c's fallback via low-level call from this contract.
    function run(uint amount, bool expectTimeAdvance) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Read before-values
        uint beforeTime = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Perform the call to fallback: send `amount` wei to c.
        bool success;
        // call must be a top-level statement
        (success, ) = address(c).call{value: amount}("");

        // Read after-values
        uint afterTime = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // Determine properties depending on success and inputs.
        // If the call reverted (success==false), then contract state must be unchanged.
        // If the call succeeded, then amount must have been exactly 10 ether and block.timestamp must have been > beforeTime.
        // On success, pastBlockTime should equal block.timestamp and balance should either increase by 10 ether
        // or be zero if the fallback transferred the whole balance out (when block.number % 15 == 0).

        assert(
            // If reverted: state unchanged
            (!success && afterTime == beforeTime && afterBal == beforeBal)
            ||
            // If succeeded: amount must be exactly 10 ether, time advanced, and balance changed appropriately
            (success
                && amount == 10 ether
                && afterTime == block.timestamp
                && (
                    // either drained to zero (drain happens only when block.number % 15 == 0)
                    (afterBal == 0)
                    // or balance increased by exactly 10 ether
                    || (afterBal == beforeBal + 10 ether)
                )
            )
        );
    }

    // Allow contract to receive Ether so test can forward funds
    receive() external payable {}
}

