contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive C by performing a low-level call with provided amount.
    // The rule: for any amount, either the call reverts and c.pastBlockTime and address(c).balance stay the same,
    // or it succeeds only when amount == 10 ether && block.timestamp > beforePast and then pastBlockTime==block.timestamp
    // and address(c).balance is either before+10 ether or 0 (if drained).
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform low-level call to invoke fallback
        (bool ok, ) = address(c).call{value: amount}("");

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // assert the general invariant described above
        // If call reverted (ok == false) then past and balance unchanged.
        // If call succeeded (ok == true) then amount must be exactly 10 ether and timestamp strictly greater than beforePast,
        // and pastBlockTime updated to current block.timestamp, and balance either increased by amount (10 ether) or is 0.
        assert(
            (!ok && afterPast == beforePast && afterBal == beforeBal)
            || (
                ok
                && amount == 10 ether
                && block.timestamp > beforePast
                && afterPast == block.timestamp
                && (afterBal == beforeBal + 10 ether || afterBal == 0)
            )
        );
    }

    receive() external payable {}
}

