contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking inputs: the ether amount to send and a dummy flag to allow arbitrary integer inputs
    function run(uint amount, uint dummy) public payable {
        // we only care about calls that send exactly 10 ether to c per C's fallback requirements
        require(amount == 10 ether);
        // ensure this contract has enough balance to forward
        require(address(this).balance >= amount);

        // observe before-values
        uint beforePast = c.pastBlockTime();
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;
        uint currentBlock = block.number;
        uint currentTime = block.timestamp;

        // perform the call; capture whether it reverted
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values (only if call did not revert we can read meaningful changes)
        uint afterPast = c.pastBlockTime();
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule (single assert):
        // - If the fallback reverted then block.timestamp must have been <= pastBlockTime or amount != 10 ether.
        //   We know amount == 10 ether by require above, so revert implies block.timestamp <= beforePast.
        // - If it did not revert then afterPast == currentTime && afterPast > beforePast (because require enforces strictly greater),
        //   and either the contract paid out its whole balance when block.number % 15 == 0 (so afterCbal == 0 and afterThis == beforeThis + beforeCbal + amount - amount),
        //   or it kept the funds (afterCbal == beforeCbal + amount and afterThis == beforeThis - amount).
        // We express this as a single boolean condition below.

        assert(
            (reverted && currentTime <= beforePast)
            || (
                !reverted
                && afterPast == currentTime
                && afterPast > beforePast
                && (
                    (currentBlock % 15 == 0 && afterCbal == 0 && afterThis >= beforeThis) // payout happened; this contract's balance increased (>= because gas/other calls not relevant)
                    || (currentBlock % 15 != 0 && afterCbal == beforeCbal + amount && afterThis == beforeThis - amount)
                )
            )
        );
    }

    // accept Ether so payouts from C can be received
    receive() external payable {}
}

