    constructor(C _c) { c = _c; }

    // Single public test function. amount is forwarded to c; must be provided by caller.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the fallback call on c as a top-level statement
        // calling the fallback is done by calling with empty calldata
        // Note: this is a state-changing interaction and must be top-level as required
        (bool ok, ) = address(c).call{value: amount}("");
        bool reverted = !ok;

        // observe after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General invariant: if the call did not revert then it sent exactly 10 ether,
        // pastBlockTime strictly increased, and either the contract retained the sent 10 ether
        // (balance increased by exactly 10 ether) or it paid out everything (balance == 0).
        assert(
            reverted || (
                amount == 10 ether
                && afterPast > beforePast
                && (afterBal == beforeBal + 10 ether || afterBal == 0)
            )
        );
    }

    // allow receiving Ether when contract C transfers out to this test
    receive() external payable {}
}

