contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // The single public test function: takes amount to send and an observed block timestamp and block number
    function run(uint amount, uint observedTimestamp, uint observedBlockNumber) public payable {
        // we will only attempt the meaningful scenario when amount == 10 ether
        require(address(this).balance >= amount);

        // read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // We cannot set the actual block.timestamp or block.number here; the test models the assumption
        // by requiring that observedTimestamp > beforePast and that observedBlockNumber is the current block.number.
        // The only external effects visible are through c's public surface and balances.
        // Call fallback by sending Ether. Must be a top-level statement.
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule: if the call did not revert and the call amount was 10 ether and the caller observed
        // a strictly increasing timestamp (observedTimestamp > beforePast), then c.pastBlockTime must have been
        // updated to the current block.timestamp; additionally, if the current block.number is divisible by 15
        // then c's balance became 0 (it paid out its full balance to msg.sender), otherwise its balance increased by 10 ether.
        // Since we cannot read block.timestamp or block.number inside this test reliably as inputs, we express
        // the rule using the observable before/after and the revert flag plus the provided observed values.
        // Note: the rule only claims consequences when the caller satisfied the preconditions for the fallback to succeed.
        assert(
            // If call succeeded AND caller provided the exact amount required AND the caller's provided observedTimestamp
            // indicates the timestamp increased relative to beforePast
            ((reverted == false) && (amount == 10 ether) && (observedTimestamp > beforePast))
            =>
            (
                // then pastBlockTime was updated to some nonzero value equal to the on-chain block.timestamp as observed via change
                (afterPast == observedTimestamp)
                &&
                // and either the contract paid out everything (balance 0) when observedBlockNumber % 15 == 0,
                // or it retained the previous balance plus the 10 ether otherwise
                ((observedBlockNumber % 15 == 0 && afterBal == 0) || (observedBlockNumber % 15 != 0 && afterBal == beforeBal + 10 ether))
            )
        );
    }

    // Accept Ether so that this contract can forward value to c
    receive() external payable {}
}

