        require(address(this).balance >= amount);

        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // make the state-changing call to C (fallback) with value = amount
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule expressed without using implication operator (=>) which is not Solidity:
        // If the call did not revert AND amount == 10 ether AND observedBlockTimestamp > beforePast,
        // then afterPast equals observedBlockTimestamp AND
        // (if observedBlockNumber % 15 == 0 then afterBal == 0 else afterBal == beforeBal + 10 ether).
        // We encode this as: either the antecedent is false, or the consequent holds.
        bool antecedent = (reverted == false) && (amount == 10 ether) && (observedBlockTimestamp > beforePast);
        bool consequentTime = (afterPast == observedBlockTimestamp);
        bool consequentBalWhenDiv = (observedBlockNumber % 15 == 0 && afterBal == 0);
