contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with all test logic
    function run(uint sendAmount, uint beforePad) public payable {
        // require we have enough balance to forward sendAmount to c
        require(address(this).balance >= sendAmount);
        // only meaningful input is 10 ether because C's fallback requires it
        // but we keep it as parameter and let the call revert otherwise

        // read observable state before the call
        uint pastBefore = c.pastBlockTime();
        uint balanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        // Must call fallback by sending to address(c)
        // Use try/catch via low-level call since fallback has no function selector
        (bool ok, ) = address(c).call{value: sendAmount}("");
        reverted = !ok;

        // read observable state after the call
        uint pastAfter = c.pastBlockTime();
        uint balanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;

        // General rule asserted for all inputs and executions:
        // If the call reverted then nothing observable in c changed.
        // If the call succeeded and sendAmount == 10 ether then exactly one of two cases holds:
        //  - if block.number % 15 == 0 then contract sent all its balance to msg.sender (test), so c.balance == 0 and this contract's balance increased by that withdrawn amount;
        //  - otherwise pastBlockTime was updated to the current block.timestamp (non-decreasing) and c retained its balance increased by sendAmount.

        assert(
            // if reverted: no observable change to c (pastBlockTime and balance unchanged)
            (reverted && pastAfter == pastBefore && balanceAfter == balanceBefore)
            ||
            // else not reverted: need to ensure sendAmount == 10 ether (fallback requires it)
            (!reverted && sendAmount == 10 ether && (
                // payout case when block.number % 15 == 0: c.balance becomes 0 and this contract gained the withdrawn amount
                (block.number % 15 == 0 && balanceAfter == 0 && myBalanceAfter >= myBalanceBefore &&
                    // the amount gained equals previous c.balance + any sent amount minus remaining (which is zero)
                    myBalanceAfter - myBalanceBefore == balanceBefore + sendAmount
                )
                ||
                // non-payout case: pastBlockTime updated to current timestamp and c retained its balance increased by sendAmount
                (block.number % 15 != 0 && pastAfter == block.timestamp && pastAfter > pastBefore && balanceAfter == balanceBefore + sendAmount)
            ))
        );
    }

    // allow receiving Ether when c transfers to this contract during the test
    receive() external payable {}
}
